import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Bedienungsanleitung","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide.md","filePath":"projects/logic-studio/user-guide.md","lastUpdated":1794775908000}'),s={name:"projects/logic-studio/user-guide.md"};function a(o,e,l,d,u,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="bedienungsanleitung" tabindex="-1">Bedienungsanleitung <a class="header-anchor" href="#bedienungsanleitung" aria-label="Permalink to &quot;Bedienungsanleitung&quot;">​</a></h1><p>Diese Anleitung richtet sich an Einsteiger. Öffne HA Logic Studio Pro in Home Assistant, wähle <strong>Neues Projekt</strong>, dann einen Editor und einen Namen. Für die Beispiele kannst du unter <strong>Einstellungen → Geräte &amp; Dienste → Helfer</strong> einen eigenen Umschalter anlegen. Im Beispiel heißt er <code>input_boolean.studio_test</code>. Verwende die tatsächliche Entitäts-ID deines Helfers.</p><h2 id="welchen-editor-brauche-ich" tabindex="-1">Welchen Editor brauche ich? <a class="header-anchor" href="#welchen-editor-brauche-ich" aria-label="Permalink to &quot;Welchen Editor brauche ich?&quot;">​</a></h2><ul><li><strong>Funktionsplan</strong> für Signale, Timer und Zähler auf einer Zeichenfläche.</li><li><strong>Rules</strong> für Regeln nach dem Muster FALLS → DANN oder SONST.</li><li><strong>Blocks A</strong> für Home-Assistant-Automationen, die du aus Blöcken zusammensetzt.</li><li><strong>Blocks JS</strong> für Skripte aus Blöcken und den ioBroker-Import.</li><li><strong>JavaScript</strong> oder <strong>TypeScript</strong> zum Schreiben eigener Skripte.</li><li><strong>HA-YAML</strong> zum Bearbeiten, Prüfen und Visualisieren von Automationen und Skripten.</li></ul><h2 id="bedienung-in-den-editoren" tabindex="-1">Bedienung in den Editoren <a class="header-anchor" href="#bedienung-in-den-editoren" aria-label="Permalink to &quot;Bedienung in den Editoren&quot;">​</a></h2><ul><li><strong>Speichern</strong> übernimmt deine Änderungen. Orange zeigt an, dass etwas geändert wurde. Grau bedeutet, dass nichts zu speichern ist.</li><li><strong>Abbrechen</strong> verwirft seit dem letzten Speichern vorgenommene Änderungen und lädt den gespeicherten Stand.</li><li><strong>Testlauf</strong> nutzt bei den Skripteditoren eine Simulation. Im Funktionsplan kannst du Eingänge in der Simulation umschalten.</li><li><strong>Play</strong> startet in Funktionsplan, Blocks JS, JavaScript und TypeScript den gespeicherten Stand in der Runtime. Dort können freigegebene HA-Aktionen echte Entitäten verändern. <strong>Stopp</strong> beendet den Lauf.</li><li><strong>Prüfen</strong> zeigt Fehler vor dem Export oder Ausführen. <strong>Exportieren</strong> erzeugt eine Datei, die du bei Bedarf in Home Assistant übernimmst.</li><li><strong>Expertenmodus</strong> im Projektmenü zeigt zusätzliche Werkzeuge des jeweiligen Editors. <strong>Protokoll</strong> zeigt Ausgaben und Fehler des geöffneten Projekts.</li></ul><h2 id="editoren" tabindex="-1">Editoren <a class="header-anchor" href="#editoren" aria-label="Permalink to &quot;Editoren&quot;">​</a></h2><ul><li><a href="./user-guide/function-plan">Funktionsplan</a></li><li><a href="./user-guide/rules">Rules</a></li><li><a href="./user-guide/blocks-a">Blocks A</a></li><li><a href="./user-guide/blocks-js">Blocks JS</a></li><li><a href="./user-guide/javascript">JavaScript</a></li><li><a href="./user-guide/typescript">TypeScript</a></li><li><a href="./user-guide/ha-yaml">HA-YAML</a></li><li><a href="./user-guide/feedback">Fehler melden und mitarbeiten</a></li></ul>',8)])])}const p=n(s,[["render",a]]);export{h as __pageData,p as default};
